<?php\n\nnamespace Config;\n\nuse PDO;\nuse PDOException;\n\nclass Database\n{\n    private $host;\n    private $port;\n    private $db_name;\n    private $username;\n    private $password;\n    private $conn;\n\n    public function __construct()\n    {\n        $env = Environment::getInstance();\n        $this->host = $env->getRequired(\'DB_HOST\');\n        $this->port = $env->getRequired(\'DB_PORT\');\n        $this->db_name = $env->getRequired(\'DB_NAME\');\n        $this->username = $env->getRequired(\'DB_USER\');\n        $this->password = $env->get(\'DB_PASSWORD\', \'\');\n    }\n\n    public function connect(): ?PDO\n    {\n        $this->conn = null;\n        $dsn = \"mysql:host={\$this->host};port={\$this->port};dbname={\$this->db_name};charset=utf8mb4\";\n\n        try {\n            $this->conn = new PDO($dsn, $this->username, $this->password);\n            $this->conn->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);\n            $this->conn->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE, PDO::FETCH_ASSOC);\n        } catch (PDOException $e) {\n            // En un entorno de producción, esto debería registrarse y no mostrarse al usuario.\n            error_log(\"Error de conexión a la base de datos: \" . $e->getMessage());\n            // Relanzar o manejar de forma más controlada para evitar exponer credenciales o detalles internos.\n            throw new \\Exception(\"No se pudo conectar a la base de datos. Por favor, inténtelo de nuevo más tarde.\");\n        }\n\n        return $this->conn;\n    }\n\n    public function getConnection(): ?PDO\n    {\n        if ($this->conn === null) {\n            return $this->connect();\n        }\n        return $this->conn;\n    }\n\n    public function disconnect()\n    {\n        $this->conn = null;\n    }\n}\n